create or replace function app.import_rows_open_orders_units(p_organization_id uuid,p_batch_id uuid,p_file_no smallint,p_from_row integer,p_to_row integer)
returns table (order_code text, line_code text, item_id uuid, location_id uuid, supplier_id uuid, expected_date date, quantity numeric(18,3), unit_cost numeric(18,3), currency char(3), status text, unit_of_measure text)
language sql stable security definer set search_path = '' as $$
select r.cells[1]::text, r.cells[2]::text, j3.id, j4.id, j5.id, r.cells[6]::date, r.cells[7]::numeric(18,3), r.cells[8]::numeric(18,3), r.cells[9]::char(3), r.cells[10]::text, nullif(r.cells[11],'') from ingest.staged_rows r
left join public.items j3 on j3.organization_id=p_organization_id and j3.code=r.cells[3] left join public.locations j4 on j4.organization_id=p_organization_id and j4.code=r.cells[4] left join public.suppliers j5 on j5.organization_id=p_organization_id and j5.code=r.cells[5]
where r.organization_id=p_organization_id and r.batch_id=p_batch_id and r.file_no=p_file_no and r.row_no between p_from_row and p_to_row;
$$;

create or replace function app.import_merge_open_orders(p_batch_id uuid,p_file_no smallint,p_from_row integer,p_to_row integer)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare v_org uuid; v_p boolean[]; v_staged integer; v_updated integer; v_inserted integer; v_missing integer;
begin
 select c.organization_id,c.provided into v_org,v_p from app.import_file_context(p_batch_id,p_file_no,'open_orders') c;
 select count(*)::integer, count(*) filter (where (v_p[3] and x.item_id is null) or (v_p[4] and x.location_id is null) or (v_p[5] and x.supplier_id is null))::integer into v_staged,v_missing from app.import_rows_open_orders_units(v_org,p_batch_id,p_file_no,p_from_row,p_to_row) x;
 perform app.import_require_resolved(v_missing);
 update public.open_orders t set unit_of_measure=case when v_p[11] then x.unit_of_measure when v_p[3] or v_p[7] or v_p[8] or v_p[9] then null else t.unit_of_measure end, item_id=case when v_p[3] then x.item_id else t.item_id end,
location_id=case when v_p[4] then x.location_id else t.location_id end,
supplier_id=case when v_p[5] then x.supplier_id else t.supplier_id end,
expected_date=case when v_p[6] then x.expected_date else t.expected_date end,
quantity=case when v_p[7] then x.quantity else t.quantity end,
unit_cost=case when v_p[8] then x.unit_cost else t.unit_cost end,
currency=case when v_p[9] then x.currency else t.currency end,
status=case when v_p[10] then x.status else t.status end from app.import_rows_open_orders_units(v_org,p_batch_id,p_file_no,p_from_row,p_to_row) x where t.organization_id=v_org and t.order_code=x.order_code and t.line_code=x.line_code and (t.unit_of_measure is distinct from (case when v_p[11] then x.unit_of_measure when v_p[3] or v_p[7] or v_p[8] or v_p[9] then null else t.unit_of_measure end) or (v_p[3] and t.item_id is distinct from x.item_id) or (v_p[4] and t.location_id is distinct from x.location_id) or (v_p[5] and t.supplier_id is distinct from x.supplier_id) or (v_p[6] and t.expected_date is distinct from x.expected_date) or (v_p[7] and t.quantity is distinct from x.quantity) or (v_p[8] and t.unit_cost is distinct from x.unit_cost) or (v_p[9] and t.currency is distinct from x.currency) or (v_p[10] and t.status is distinct from x.status));
 get diagnostics v_updated = row_count;
 insert into public.open_orders(organization_id,order_code,line_code,item_id,location_id,supplier_id,expected_date,quantity,unit_cost,currency,status,unit_of_measure)
 select v_org,x.order_code, x.line_code, x.item_id, x.location_id, x.supplier_id, x.expected_date, x.quantity, x.unit_cost, x.currency, coalesce(x.status,'open'::text), x.unit_of_measure from app.import_rows_open_orders_units(v_org,p_batch_id,p_file_no,p_from_row,p_to_row) x where not exists(select 1 from public.open_orders t where t.organization_id=v_org and t.order_code=x.order_code and t.line_code=x.line_code);
 get diagnostics v_inserted = row_count;
 return app.import_counts(v_staged,v_inserted,v_updated,0,0);
end; $$;


revoke all on function app.import_rows_open_orders_units(uuid,uuid,smallint,integer,integer) from public,anon,authenticated,service_role,maqdar_worker;
alter type ingest.api_record_open_orders drop attribute updated_at;
alter type ingest.api_record_open_orders add attribute unit_of_measure text;
alter type ingest.api_record_open_orders add attribute updated_at text;
create or replace function public.api_list(
  p_key_hash bytea,
  p_entity text,
  p_after text default null,
  p_limit integer default null,
  p_updated_since timestamptz default null
)
returns json
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_org uuid;
  v_key uuid;
  v_limit integer := coalesce(p_limit, 100);
  v_after uuid := '00000000-0000-0000-0000-000000000000';
  v_since timestamptz := p_updated_since;
  v_since_text text := to_char(p_updated_since at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"');
  v_as_of text := to_char(now() at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"');
  v_cursor jsonb;
  v_data json;
  v_count integer;
  v_last uuid;
  v_next text;
begin
  select a.organization_id, a.api_key_id into v_org, v_key from app.api_authorize(p_key_hash, case when p_entity in ('stock_snapshots','open_orders','receipts') then 'transactions:read' else 'master_data:read' end) as a;
  if p_entity is null or p_entity = 'demand_history'
     or not exists (select 1 from ingest.contract_entities e where e.entity = p_entity) then
    raise exception using errcode = 'MQ404', message = 'no such resource', hint = 'resource';
  end if;
  if v_limit not between 1 and 1000 then
    raise exception using errcode = 'MQ422', message = 'limit is 1 to 1000', hint = 'limit';
  end if;
  if p_updated_since is not null and not isfinite(p_updated_since) then
    raise exception using errcode = 'MQ422', message = 'updated_since is a finite timestamp', hint = 'updated_since';
  end if;
  if p_after is not null then
    v_cursor := app.api_cursor_decode(p_after, p_entity);
    if not coalesce(
         jsonb_typeof(v_cursor -> 'a') = 'string' and pg_catalog.pg_input_is_valid(v_cursor ->> 'a', 'uuid')
         and jsonb_typeof(v_cursor -> 't') = 'string'
         and (v_cursor ->> 't') ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{6}Z$'
         and pg_catalog.pg_input_is_valid(v_cursor ->> 't', 'timestamptz')
         and v_cursor ? 'u'
         and (jsonb_typeof(v_cursor -> 'u') = 'null'
              or (jsonb_typeof(v_cursor -> 'u') = 'string'
                  and (v_cursor ->> 'u') ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{6}Z$'
                  and pg_catalog.pg_input_is_valid(v_cursor ->> 'u', 'timestamptz'))),
         false) then
      raise exception using errcode = 'MQ422', message = 'invalid cursor', hint = 'cursor';
    end if;
    if (v_cursor ->> 'u')::timestamptz is distinct from p_updated_since then
      raise exception using errcode = 'MQ422', message = 'this cursor belongs to another updated_since', hint = 'cursor';
    end if;
    v_after := (v_cursor ->> 'a')::uuid;
    v_as_of := v_cursor ->> 't';
  end if;

  if p_entity = 'work_calendars' then
    select coalesce(json_agg(x.rec order by x.n) filter (where x.n <= v_limit), '[]'::json), count(*)::integer,
           (array_agg(x.id) filter (where x.n = v_limit))[1]
      into v_data, v_count, v_last
    from (
      select t.id, row_number() over (order by t.id) as n,
             row(t.code, t.name_en, t.name_ar, t.country_code::text,
                 array(select d.v from unnest(t.weekend_days) as d(v) order by d.v),
                 t.observe_public_holidays, t.is_active,
                 to_char(t.updated_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'))::ingest.api_record_work_calendars as rec
      from (
        select w.id, w.code, w.name_en, w.name_ar, w.country_code, w.weekend_days, w.observe_public_holidays, w.is_active, w.updated_at
        from public.work_calendars w
        where w.organization_id = v_org and w.id > v_after and (v_since is null or w.updated_at >= v_since)
        order by w.id
        limit v_limit + 1
