    from (
      select t.id, row_number() over (order by t.id) as n,
             row(t.code, t.name_en, t.name_ar, t.country_code::text, t.currency::text, t.lead_time_days_p50, t.lead_time_days_p90,
                 t.is_active, wc.code,
                 to_char(t.updated_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'))::ingest.api_record_suppliers as rec
      from (
        select s.id, s.code, s.name_en, s.name_ar, s.country_code, s.currency, s.lead_time_days_p50, s.lead_time_days_p90,
               s.is_active, s.work_calendar_id, s.updated_at
        from public.suppliers s
        where s.organization_id = v_org and s.id > v_after and (v_since is null or s.updated_at >= v_since)
        order by s.id
        limit v_limit + 1
      ) as t
      left join lateral (
        select w.code from public.work_calendars w where w.organization_id = v_org and w.id = t.work_calendar_id
      ) as wc on true
    ) as x;
  elsif p_entity = 'supplier_items' then
    select coalesce(json_agg(x.rec order by x.n) filter (where x.n <= v_limit), '[]'::json), count(*)::integer,
           (array_agg(x.id) filter (where x.n = v_limit))[1]
      into v_data, v_count, v_last
    from (
      select t.id, row_number() over (order by t.id) as n,
             row(sp.code, it.code, t.supplier_part_number, t.lead_time_days, t.lead_time_days_p90,
                 trim_scale(t.min_order_quantity)::text, trim_scale(t.pack_size)::text, trim_scale(t.unit_price)::text,
                 t.currency::text, t.is_preferred, t.valid_from,
                 to_char(t.updated_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'))::ingest.api_record_supplier_items as rec
      from (
        select si.id, si.supplier_id, si.item_id, si.supplier_part_number, si.lead_time_days, si.lead_time_days_p90,
               si.min_order_quantity, si.pack_size, si.unit_price, si.currency, si.is_preferred, si.valid_from, si.updated_at
        from public.supplier_items si
        where si.organization_id = v_org and si.id > v_after and (v_since is null or si.updated_at >= v_since)
        order by si.id
        limit v_limit + 1
      ) as t
      left join lateral (
        select s.code from public.suppliers s where s.organization_id = v_org and s.id = t.supplier_id
      ) as sp on true
      left join lateral (
        select i.code from public.items i where i.organization_id = v_org and i.id = t.item_id
      ) as it on true
    ) as x;
  elsif p_entity = 'stock_snapshots' then
    select coalesce(json_agg(x.rec order by x.n) filter (where x.n<=v_limit),'[]'::json),count(*)::integer,(array_agg(x.id) filter(where x.n=v_limit))[1]
    into v_data,v_count,v_last from (
      select t.id,row_number() over(order by t.id) as n,row(j1.code,j2.code,t.snapshot_date::text,t.quantity::text,t.allocated_quantity::text,t.unit_cost::text,t.currency::text,t.unit_of_measure,to_char(t.updated_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'))::ingest.api_record_stock_snapshots as rec
      from (select * from public.stock_snapshots where organization_id=v_org and id>v_after and (v_since is null or updated_at>=v_since) order by id limit v_limit+1) t
      join public.items j1 on j1.organization_id=t.organization_id and j1.id=t.item_id join public.locations j2 on j2.organization_id=t.organization_id and j2.id=t.location_id
    ) x;
  elsif p_entity = 'open_orders' then
    select coalesce(json_agg(x.rec order by x.n) filter (where x.n<=v_limit),'[]'::json),count(*)::integer,(array_agg(x.id) filter(where x.n=v_limit))[1]
    into v_data,v_count,v_last from (
      select t.id,row_number() over(order by t.id) as n,row(t.order_code::text,t.line_code::text,j3.code,j4.code,j5.code,t.expected_date::text,t.quantity::text,t.unit_cost::text,t.currency::text,t.status::text,t.unit_of_measure,to_char(t.updated_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'))::ingest.api_record_open_orders as rec
      from (select * from public.open_orders where organization_id=v_org and id>v_after and (v_since is null or updated_at>=v_since) order by id limit v_limit+1) t
      join public.items j3 on j3.organization_id=t.organization_id and j3.id=t.item_id join public.locations j4 on j4.organization_id=t.organization_id and j4.id=t.location_id join public.suppliers j5 on j5.organization_id=t.organization_id and j5.id=t.supplier_id
    ) x;
  elsif p_entity = 'receipts' then
    select coalesce(json_agg(x.rec order by x.n) filter (where x.n<=v_limit),'[]'::json),count(*)::integer,(array_agg(x.id) filter(where x.n=v_limit))[1]
    into v_data,v_count,v_last from (
      select t.id,row_number() over(order by t.id) as n,row(t.receipt_code::text,t.line_code::text,j3.code,j4.code,j5.code,t.receipt_date::text,t.quantity::text,t.unit_cost::text,t.currency::text,to_char(t.updated_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'))::ingest.api_record_receipts as rec
      from (select * from public.receipts where organization_id=v_org and id>v_after and (v_since is null or updated_at>=v_since) order by id limit v_limit+1) t
      join public.items j3 on j3.organization_id=t.organization_id and j3.id=t.item_id join public.locations j4 on j4.organization_id=t.organization_id and j4.id=t.location_id join public.suppliers j5 on j5.organization_id=t.organization_id and j5.id=t.supplier_id
    ) x;
  elsif p_entity = 'fx_rates' then
    select coalesce(json_agg(x.rec order by x.n) filter (where x.n <= v_limit), '[]'::json), count(*)::integer,
           (array_agg(x.id) filter (where x.n = v_limit))[1]
      into v_data, v_count, v_last
    from (
      select t.id, row_number() over (order by t.id) as n,
             row(t.from_currency::text, t.to_currency::text, t.valid_from, trim_scale(t.rate)::text, t.note,
                 to_char(t.updated_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'))::ingest.api_record_fx_rates as rec
      from (
        select f.id, f.from_currency, f.to_currency, f.valid_from, f.rate, f.note, f.updated_at
        from public.fx_rates f
        where f.organization_id = v_org and f.id > v_after and (v_since is null or f.updated_at >= v_since)
        order by f.id
        limit v_limit + 1
      ) as t
    ) as x;
  end if;

  if v_count > v_limit then
    v_next := app.api_cursor_encode(jsonb_build_object('v', 1, 'k', p_entity, 'a', v_last, 'u', v_since_text, 't', v_as_of));
  end if;
  return json_build_object('data', v_data, 'next_cursor', v_next, 'as_of', v_as_of);
end;
$$;


-- Preview uses one statement snapshot. Explicit authorization also protects calls
-- made by the definer save RPC; RLS protects direct session calls independently.
create function public.replenishment_preview(p_organization_id uuid,p_policy_id uuid,p_basis text,p_override_id uuid default null,p_backorders text default null,p_orders_confirmed boolean default null)
returns jsonb language plpgsql stable security invoker set search_path='' as $$
declare p public.inventory_policies; comparison jsonb; result jsonb; cutoff date; protection_end date;
  lines jsonb; inbound numeric; position numeric; gap numeric; status text; backorders numeric;
  line_count integer; unknown_units boolean; mismatched_units boolean;
begin
  if p_organization_id is null or not(p_organization_id=any(array(select app.member_organizations()))) then
    raise exception using errcode='MQ404',message='no such policy';
  end if;
  select * into p from public.inventory_policies where organization_id=p_organization_id and id=p_policy_id
    and (organization_id=any(array(select app.unscoped_organizations())) or location_id=any(array(select app.scoped_locations())));
  if not found then raise exception using errcode='MQ404',message='no such policy'; end if;
  if p_backorders is null or p_backorders!~'^[0-9]{1,15}(\.[0-9]{1,3})?$' or p_orders_confirmed is null then
    raise exception using errcode='MQ422',message='enter additional unallocated backorders and confirmation';
  end if;
  backorders:=p_backorders::numeric(18,3);
  cutoff:=(p.evidence->'forecast'->>'to_date')::date;
  comparison:=public.policy_stock_comparison(p_organization_id,p.id,cutoff,p_basis,p_override_id);
  protection_end:=cutoff+(p.evidence->'options'->>'lead_time')::integer+(p.evidence->'options'->>'review_interval')::integer;
  status:=comparison->>'status';
  if p.evidence->'forecast'->>'method'='regional-v1' or p.evidence->'forecast'->'source' ? 'preparation' then
    status:='prepared_group';
  elsif status='available' and (comparison->'snapshot'->>'date')::date is distinct from cutoff then
    status:='stock_date_mismatch';
  end if;
  -- All positive outstanding inbound counts, regardless of arrival date or supplier.
  -- Limit plus one proves completeness; never compute from a truncated line set.
  select count(*)::integer,coalesce(sum(o.quantity),0),coalesce(bool_or(o.unit_of_measure is null),false),
    coalesce(bool_or(o.unit_of_measure is distinct from p.unit),false),
    coalesce(jsonb_agg(jsonb_build_object('id',o.id,'order_code',o.order_code,'line_code',o.line_code,
      'supplier_id',o.supplier_id,'supplier_code',s.code,'expected_date',o.expected_date,
      'quantity',o.quantity::text,'unit',o.unit_of_measure,'updated_at',o.updated_at,
      'overdue',o.expected_date<cutoff,'late',o.expected_date>protection_end) order by o.expected_date,o.id),'[]'::jsonb)
    into line_count,inbound,unknown_units,mismatched_units,lines
  from (select * from public.open_orders orders where orders.organization_id=p_organization_id and orders.item_id=p.item_id
    and orders.location_id=p.location_id and orders.status='open' and orders.quantity>0 order by orders.expected_date,orders.id limit 1001) o
  left join public.suppliers s on s.organization_id=p_organization_id and s.id=o.supplier_id;
  if status='available' then
    status:=case when protection_end is null then 'policy_unavailable'
      when line_count>1000 then 'inbound_limit'
      when unknown_units then 'inbound_unit_unknown'
      when mismatched_units then 'inbound_unit_mismatch'
      when not p_orders_confirmed then 'orders_unconfirmed' else 'available' end;
  end if;
  if line_count>1000 then lines:='[]'::jsonb; end if;
  if line_count>1000 or unknown_units or mismatched_units or not p_orders_confirmed then inbound:=null; end if;
  if status='prepared_group' then
    -- A representative item's orders are not evidence for a prepared pool.
    lines:='[]'::jsonb; inbound:=null; line_count:=0;
  elsif status in ('policy_unavailable','policy_unit_unknown') then inbound:=null;
  end if;
  if status='available' then
    position:=(comparison->'snapshot'->>'available')::numeric+inbound-backorders;
    gap:=greatest((comparison->>'maximum')::numeric-position,0);
    if gap>999999999999999.999 then status:='quantity_out_of_range'; gap:=null; end if;
  end if;
  result:=jsonb_build_object('method','replenishment-gap-v1','status',status,'policy',comparison,
    'location_id',p.location_id,'protection_end',protection_end,'backorders',backorders::text,
    'orders_confirmed',p_orders_confirmed,'orders',lines,'orders_truncated',line_count>1000,
    'inbound_quantity',inbound::text,'inventory_position',position::text,'gap',gap::text);
  return result||jsonb_build_object('fingerprint',encode(sha256(convert_to(result::text,'UTF8')),'hex'));
end; $$;
revoke all on function public.replenishment_preview(uuid,uuid,text,uuid,text,boolean) from public,anon,authenticated,service_role,maqdar_worker;
grant execute on function public.replenishment_preview(uuid,uuid,text,uuid,text,boolean) to authenticated;

create table public.replenishment_drafts (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null,
  policy_id uuid not null,
  location_id uuid not null,
  request_id uuid not null,
  submitted_by uuid not null,
  created_at timestamptz not null default clock_timestamp(),
  report jsonb not null,
  unique(organization_id,id),
  unique(organization_id,request_id),
  foreign key(organization_id,policy_id,location_id) references public.inventory_policies(organization_id,id,location_id) on delete cascade
);
comment on table public.replenishment_drafts is 'Immutable stock-and-inbound scenarios. Completeness/as-of is planner attestation, not historical reconstruction. No order execution.';
create index replenishment_drafts_recent on public.replenishment_drafts(organization_id,created_at desc,id desc);
create index replenishment_drafts_policy on public.replenishment_drafts(organization_id,policy_id,location_id);
alter table public.replenishment_drafts enable row level security;
revoke all on public.replenishment_drafts from public,anon,authenticated,service_role,maqdar_worker;
grant select on public.replenishment_drafts to authenticated;
create policy "members read" on public.replenishment_drafts for select to authenticated using(organization_id=any(array(select app.member_organizations())));
create policy "branch scope" on public.replenishment_drafts as restrictive for select to authenticated using(organization_id=any(array(select app.unscoped_organizations())) or location_id=any(array(select app.scoped_locations())));
create trigger audit_business_row after insert or update or delete on public.replenishment_drafts for each row execute function app.audit_business_row();

create function public.replenishment_save(p_organization_id uuid,p_policy_id uuid,p_request_id uuid,p_basis text,p_override_id uuid default null,p_backorders text default null,p_orders_confirmed boolean default null,p_fingerprint text default null)
returns uuid language plpgsql security definer set search_path='' as $$
declare previous public.replenishment_drafts; report jsonb; result uuid;
begin
  if p_organization_id is null or auth.uid() is null or not(p_organization_id=any(array(select app.editable_organizations()))) then
    raise exception using errcode='MQ403',message='draft requires an editor';
  end if;
  if p_request_id is null or p_fingerprint is null or p_fingerprint!~'^[a-f0-9]{64}$'
    or p_backorders is null or p_backorders!~'^[0-9]{1,15}(\.[0-9]{1,3})?$' or p_orders_confirmed is null then
    raise exception using errcode='MQ422',message='invalid draft request';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('maqdar.replenishment:'||p_organization_id::text,0));
  -- A queued save must recheck edit authority after another transaction commits.
  if not(p_organization_id=any(array(select app.editable_organizations()))) then
    raise exception using errcode='MQ403',message='draft requires an editor';
  end if;
  select * into previous from public.replenishment_drafts where organization_id=p_organization_id and request_id=p_request_id
    and (organization_id=any(array(select app.unscoped_organizations())) or location_id=any(array(select app.scoped_locations())));
  if found then
    if previous.policy_id=p_policy_id and previous.submitted_by=auth.uid() and previous.report->>'fingerprint'=p_fingerprint
      and previous.report->'policy'->>'basis'=p_basis
      and (previous.report->'policy'->>'override_id')::uuid is not distinct from p_override_id
      and (previous.report->>'backorders')::numeric=p_backorders::numeric
      and (previous.report->>'orders_confirmed')::boolean=p_orders_confirmed then return previous.id; end if;
    raise exception using errcode='MQ409',message='draft request conflicts';
  end if;
  report:=public.replenishment_preview(p_organization_id,p_policy_id,p_basis,p_override_id,p_backorders,p_orders_confirmed);
  if report->>'fingerprint'<>p_fingerprint then
    raise exception using errcode='MQ409',message='inputs changed; refresh the preview';
  end if;
  insert into public.replenishment_drafts(organization_id,policy_id,location_id,request_id,submitted_by,report)
    values(p_organization_id,p_policy_id,(report->>'location_id')::uuid,p_request_id,auth.uid(),report) returning id into result;
  return result;
end; $$;
revoke all on function public.replenishment_save(uuid,uuid,uuid,text,uuid,text,boolean,text) from public,anon,authenticated,service_role,maqdar_worker;
grant execute on function public.replenishment_save(uuid,uuid,uuid,text,uuid,text,boolean,text) to authenticated;

create view public.replenishment_draft_list with(security_invoker=true) as
select id,organization_id,policy_id,location_id,submitted_by,created_at,
  report->'policy'->>'item_code' item_code,report->'policy'->>'location_code' location_code,
  report->'policy'->>'cutoff' cutoff,report->'policy'->>'unit' unit,report->'policy'->>'basis' basis,
  report->>'status' status,report->>'gap' gap,app.normalize_search(report->'policy'->>'item_code') search_text
from public.replenishment_drafts;
revoke all on public.replenishment_draft_list from public,anon,authenticated,service_role,maqdar_worker;
grant select on public.replenishment_draft_list to authenticated;
reset lock_timeout;
